    private void testLandscape(){Activity a=startActivitySync(new Intent(getTargetContext(),MainActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));waitForIdleSync();check(a.getResources().getConfiguration().orientation==2,"landscape did not launch");runOnMainSync(()->checkButtonText(a.getWindow().getDecorView()));runOnMainSync(a::finish);}
    private void checkButtonText(android.view.View view){if(view instanceof android.widget.Button){android.widget.Button button=(android.widget.Button)view;android.graphics.Rect visible=new android.graphics.Rect();if(button.getGlobalVisibleRect(visible)&&visible.height()==button.getHeight()){android.graphics.Paint.FontMetricsInt metrics=button.getPaint().getFontMetricsInt();check(button.getHeight()>=button.getCompoundPaddingTop()+button.getCompoundPaddingBottom()+metrics.descent-metrics.ascent,"clipped button: "+button.getText());}}if(view instanceof android.view.ViewGroup){android.view.ViewGroup group=(android.view.ViewGroup)view;for(int i=0;i<group.getChildCount();i++)checkButtonText(group.getChildAt(i));}}
    private String read(String name)throws Exception{try(InputStream in=getContext().getAssets().open(name)){ByteArrayOutputStream out=new ByteArrayOutputStream();byte[] b=new byte[4096];int n;while((n=in.read(b))!=-1)out.write(b,0,n);return out.toString("UTF-8");}}
