    private void testPromptCancellation()throws Exception{String id="prompt-fixture";fixture(id,read("prompt-fixture.js"),new JSONArray()).dispose();Activity activity=startActivitySync(new Intent(getTargetContext(),MainActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));waitForIdleSync();PluginRuntime runtime=new PluginRuntime(activity,new File(getTargetContext().getCacheDir(),id));runtimes.add(runtime);java.lang.reflect.Field field=PluginRuntime.class.getDeclaredField("loginDialog");field.setAccessible(true);CountDownLatch completed=new CountDownLatch(1);boolean[] ok={true};runtime.call("signIn",new JSONObject(),(success,raw)->{ok[0]=success;completed.countDown();});boolean[] showing={false};long deadline=android.os.SystemClock.elapsedRealtime()+7000;while(!showing[0]&&android.os.SystemClock.elapsedRealtime()<deadline){runOnMainSync(()->{try{AlertDialog dialog=(AlertDialog)field.get(runtime);showing[0]=dialog!=null&&dialog.isShowing();}catch(Exception ignored){}});android.os.SystemClock.sleep(50);}try{check(showing[0],"login prompt not shown");runOnMainSync(()->{try{((AlertDialog)field.get(runtime)).getButton(AlertDialog.BUTTON_NEGATIVE).performClick();}catch(Exception e){throw new RuntimeException(e);}});check(completed.await(5,TimeUnit.SECONDS)&&!ok[0],"closing QR prompt did not cancel login");android.os.SystemClock.sleep(300);runOnMainSync(()->{try{AlertDialog dialog=(AlertDialog)field.get(runtime);check(runtime.isClosed()&&!dialog.isShowing(),"cancelled login reopened its prompt");}catch(IllegalAccessException e){throw new RuntimeException(e);}});PluginRuntime restored=fixture(id,read("prompt-fixture.js"),new JSONArray());check(call(restored,"saved",new JSONObject()).contains("keep"),"cancelling login erased the previous session");}finally{runtime.dispose();runOnMainSync(activity::finish);}}
